<template><div class="game-container"><header><router-link to="/" class="back-link">← 返回</router-link><h1>🐾 动物消消乐</h1></header><main><div class="game-info"><div class="score-box"><div class="score-label">分数</div><div class="score-value">{{ score }}</div></div><div class="score-box"><div class="score-label">最高分</div><div class="score-value">{{ bestScore }}</div></div><div class="combo-display" v-if="combo > 1">{{ combo }}连击! 🎉</div></div><div class="board-container" ref="boardRef"><div class="grid-background"><div v-for="i in 64" :key="'cell-'+i" class="grid-cell"></div></div><div class="tiles-container"><div v-for="(tile, index) in board" :key="tile.id" class="tile" :class="{ selected: selectedIndex === index, matched: tile.matched }" :style="getTileStyle(index)" @click="handleTileClick(index)"><span class="tile-emoji">{{ tile.emoji }}</span></div></div></div><div class="controls"><button @click="restartGame" class="btn btn-primary">重新开始</button></div><div class="game-controls"><h3>操作说明</h3><div class="control-methods"><div class="control-item"><strong>游戏玩法</strong><p>点击选择一个动物，再点击相邻动物交换</p></div><div class="control-item"><strong>消除规则</strong><p>3个或更多相同动物连成一线即可消除</p></div></div></div><div class="game-rules"><h3>游戏规则</h3><ul><li>交换相邻两个动物形成3个或更多连线</li><li>消除后上面的动物掉落，新动物补充</li><li>连击获得额外分数！无限玩挑战最高分！</li></ul></div></main><footer><p>经典消除游戏 - 动物消消乐</p></footer></div></template><script setup>import { ref, onMounted } from 'vue';import { useRouter } from 'vue-router';const router = useRouter();const boardRef = ref(null);const GRID_SIZE = 8;const ANIMALS = ['🐱', '🐶', '🐰', '🦊', '🐻', '🐼'];const board = ref([]);const score = ref(0);const bestScore = ref(parseInt(localStorage.getItem('animal-match-best')) || 0);const selectedIndex = ref(null);const combo = ref(0);let nextTileId = 1;let isAnimating = false;const createBoard = () => {board.value = [];for (let r = 0; r < GRID_SIZE; r++) {for (let c = 0; c < GRID_SIZE; c++) {let emoji;do {emoji = ANIMALS[Math.floor(Math.random() * ANIMALS.length)];} while (wouldCreateMatch(r, c, emoji));board.value.push({id: nextTileId++,emoji: emoji,matched: false,special: null});}}};const wouldCreateMatch = (row, col, emoji) => {let horizontalCount = 1;for (let c = col - 1; c >= 0; c--) {const index = row * GRID_SIZE + c;if (board.value[index]?.emoji === emoji) horizontalCount++;else break;}if (horizontalCount >= 3) return true;let verticalCount = 1;for (let r = row - 1; r >= 0; r--) {const index = r * GRID_SIZE + col;if (board.value[index]?.emoji === emoji) verticalCount++;else break;}return verticalCount >= 3;};const getTileStyle = (index) => {const row = Math.floor(index / GRID_SIZE);const col = index % GRID_SIZE;const size = 50;const padding = 5;const x = col * (size + padding) + padding;const y = row * (size + padding) + padding;return {left: x + 'px',top: y + 'px',width: size + 'px',height: size + 'px',fontSize: '32px'};};const handleTileClick = (index) => {if (isAnimating) return;if (selectedIndex.value === null) {selectedIndex.value = index;} else {if (isAdjacent(selectedIndex.value, index)) {swapTiles(selectedIndex.value, index);}selectedIndex.value = null;}};const isAdjacent = (idx1, idx2) => {const row1 = Math.floor(idx1 / GRID_SIZE);const col1 = idx1 % GRID_SIZE;const row2 = Math.floor(idx2 / GRID_SIZE);const col2 = idx2 % GRID_SIZE;return (Math.abs(row1 - row2) + Math.abs(col1 - col2)) === 1;};const swapTiles = async (idx1, idx2) => {const temp = { ...board.value[idx1] };board.value[idx1] = { ...board.value[idx2], id: board.value[idx1].id };board.value[idx2] = { ...temp, id: board.value[idx2].id };const matches = findMatches();if (matches.length > 0) {await processMatches();} else {const temp2 = { ...board.value[idx1] };board.value[idx1] = { ...board.value[idx2], id: board.value[idx1].id };board.value[idx2] = { ...temp2, id: board.value[idx2].id };}};const findMatches = () => {const matches = [];for (let r = 0; r < GRID_SIZE; r++) {let count = 1;let startCol = 0;for (let c = 1; c < GRID_SIZE; c++) {const curr = board.value[r * GRID_SIZE + c];const prev = board.value[r * GRID_SIZE + (c - 1)];if (curr?.emoji === prev?.emoji) {count++;} else {if (count >= 3) {for (let i = startCol; i < c; i++) matches.push(r * GRID_SIZE + i);}count = 1;startCol = c;}}if (count >= 3) {for (let i = startCol; i < GRID_SIZE; i++) matches.push(r * GRID_SIZE + i);}}for (let c = 0; c < GRID_SIZE; c++) {let count = 1;let startRow = 0;for (let r = 1; r < GRID_SIZE; r++) {const curr = board.value[r * GRID_SIZE + c];const prev = board.value[(r - 1) * GRID_SIZE + c];if (curr?.emoji === prev?.emoji) {count++;} else {if (count >= 3) {for (let i = startRow; i < r; i++) matches.push(i * GRID_SIZE + c);}count = 1;startRow = r;}}if (count >= 3) {for (let i = startRow; i < GRID_SIZE; i++) matches.push(i * GRID_SIZE + c);}}return [...new Set(matches)];};const processMatches = async () => {isAnimating = true;combo.value++;let matches = findMatches();while (matches.length > 0) {const points = matches.length * 10 * combo.value;score.value += points;matches.forEach(idx => {board.value[idx].matched = true;});await delay(300);await dropAndFill(matches);matches = findMatches();if (matches.length > 0) combo.value++;}if (score.value > bestScore.value) {bestScore.value = score.value;localStorage.setItem('animal-match-best', bestScore.value);}combo.value = 0;isAnimating = false;};const dropAndFill = async (toRemove) => {for (let c = 0; c < GRID_SIZE; c++) {const column = [];for (let r = 0; r < GRID_SIZE; r++) {const idx = r * GRID_SIZE + c;if (!toRemove.includes(idx)) {column.push(board.value[idx]);}}while (column.length < GRID_SIZE) {column.unshift({id: nextTileId++,emoji: ANIMALS[Math.floor(Math.random() * ANIMALS.length)],matched: false,special: null});}for (let r = 0; r < GRID_SIZE; r++) {board.value[r * GRID_SIZE + c] = column[r];}}await delay(100);};const delay = (ms) => new Promise(resolve => setTimeout(resolve, ms));const restartGame = () => {score.value = 0;combo.value = 0;selectedIndex.value = null;isAnimating = false;createBoard();};onMounted(() => {createBoard();});</script><style scoped>.game-container {max-width: 900px;margin: 0 auto;padding: 20px;}header {position: relative;text-align: center;color: white;margin-bottom: 30px;}h1 {font-size: 3em;margin: 0;background: linear-gradient(135deg, #667eea, #764ba2);-webkit-background-clip: text;-webkit-text-fill-color: transparent;background-clip: text;}.back-link {position: absolute;left: 0;top: 50%;transform: translateY(-50%);color: white;text-decoration: none;padding: 8px 16px;background: rgba(255,255,255,0.15);border-radius: 20px;border: 1px solid rgba(255,255,255,0.2);}main {background: linear-gradient(135deg, #fff, #f8f9fa);border-radius: 20px;padding: 30px;box-shadow: 0 20px 60px rgba(0,0,0,0.3);}.game-info {display: flex;justify-content: center;align-items: center;gap: 20px;margin-bottom: 25px;flex-wrap: wrap;}.score-box {background: linear-gradient(135deg, #667eea, #764ba2);padding: 10px 25px;border-radius: 10px;text-align: center;min-width: 100px;}.score-label {color: #ddd;font-size: 0.9em;font-weight: bold;}.score-value {color: white;font-size: 1.8em;font-weight: bold;}.combo-display {color: #ffd700;font-size: 1.5em;font-weight: bold;text-shadow: 0 0 10px rgba(255,215,0,0.5);animation: combo-pulse 0.5s ease-in-out;}@keyframes combo-pulse {0%, 100% { transform: scale(1); }50% { transform: scale(1.2); }}.board-container {position: relative;width: 450px;height: 450px;margin: 0 auto;background: #1a1a2e;border-radius: 15px;padding: 10px;box-sizing: border-box;}.grid-background,.tiles-container {position: absolute;top: 10px;left: 10px;width: 430px;height: 430px;display: grid;grid-template-columns: repeat(8, 50px);grid-template-rows: repeat(8, 50px);gap: 5px;}.grid-cell {background: rgba(255,255,255,0.1);border-radius: 10px;}.tile {position: absolute;width: 50px;height: 50px;display: flex;justify-content: center;align-items: center;cursor: pointer;border-radius: 10px;transition: all 0.15s ease;user-select: none;background: rgba(255,255,255,0.95);box-shadow: 0 2px 8px rgba(0,0,0,0.1);}.tile:hover {transform: scale(1.05);box-shadow: 0 4px 15px rgba(102,126,234,0.4);}.tile.selected {transform: scale(1.1);box-shadow: 0 0 20px rgba(102,126,234,0.7),0 4px 15px rgba(102,126,234,0.4);border: 3px solid #667eea;}.tile.matched {animation: match-pop 0.3s ease-out forwards;}@keyframes match-pop {0% { transform: scale(1); opacity: 1; }50% { transform: scale(1.3); opacity: 0.8; }100% { transform: scale(0); opacity: 0; }}.tile-emoji {font-size: 32px;line-height: 1;}.controls {display: flex;justify-content: center;gap: 15px;margin: 25px 0;flex-wrap: wrap;}.btn {padding: 14px 35px;font-size: 1.1em;border: none;border-radius: 30px;cursor: pointer;transition: all 0.3s ease;font-weight: bold;}.btn-primary {background: linear-gradient(135deg, #667eea, #764ba2);color: white;box-shadow: 0 6px 20px rgba(102,126,234,0.4);}.game-controls,.game-rules {margin-top: 30px;padding: 25px;border-radius: 15px;}.game-controls {background: linear-gradient(135deg, #f5f7fa, #c3cfe2);}.game-rules {background: linear-gradient(135deg, #ffecd2, #fcb69f);}.game-controls h3,.game-rules h3 {margin-bottom: 15px;text-align: center;color: #667eea;}.control-methods {display: grid;grid-template-columns: repeat(auto-fit,minmax(250px,1fr));gap: 15px;}.control-item {padding: 15px;background: white;border-radius: 10px;}.game-rules ul {list-style: none;padding-left: 0;}.game-rules li {padding: 10px 0;padding-left: 25px;position: relative;color: #333;}footer {text-align: center;color: white;margin-top: 30px;padding: 20px;opacity: 0.9;}@media(max-width:768px) {.board-container {width: 320px;height: 320px;}.grid-background,.tiles-container {width: 300px;height: 300px;grid-template-columns: repeat(8, 35px);grid-template-rows: repeat(8, 35px);gap: 3px;}.tile {width: 35px;height: 35px;}.tile-emoji {font-size: 22px;}}</style>